import{_ as t,o as a,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Hot-Swap Implementation and Rollback","description":"","frontmatter":{"work_package_id":"WP02","title":"Hot-Swap Implementation and Rollback","lane":"done","dependencies":["WP01"],"base_branch":"013-renderer-switch-transaction-WP01","base_commit":"c50a79b1b9987f1e4163a5aa7079bad940c79ac1","created_at":"2026-03-01T13:31:18.415662+00:00","subtasks":["T006","T007","T008","T009","T010"],"phase":"Phase 2 - Core Switching","assignee":"","agent":"claude-haiku","shell_pid":"61191","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/013-renderer-switch-transaction/tasks/WP02-hot-swap-implementation-and-rollback.md","filePath":"specs/013-renderer-switch-transaction/tasks/WP02-hot-swap-implementation-and-rollback.md"}'),o={name:"specs/013-renderer-switch-transaction/tasks/WP02-hot-swap-implementation-and-rollback.md"};function s(l,e,n,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="work-package-prompt-wp02-hot-swap-implementation-and-rollback" tabindex="-1">Work Package Prompt: WP02 - Hot-Swap Implementation and Rollback <a class="header-anchor" href="#work-package-prompt-wp02-hot-swap-implementation-and-rollback" aria-label="Permalink to &quot;Work Package Prompt: WP02 - Hot-Swap Implementation and Rollback&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement the hot-swap renderer transition path that atomically transitions all active terminals from source to target renderer.</li><li>Implement automatic rollback that restores the previous renderer on any failure during the switch.</li><li>Enforce concurrent switch rejection with clear error feedback.</li></ul><p>Success criteria:</p><ul><li>Hot-swap completes in under 3 seconds with zero dropped PTY bytes.</li><li>Injected failures during any phase trigger automatic rollback restoring original renderer state.</li><li>Concurrent switch requests are rejected with informative error including transaction status.</li><li>Scrollback, cursor position, environment, and working directory are preserved across hot-swap and rollback.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/013-renderer-switch-transaction/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/013-renderer-switch-transaction/spec.md</code></li><li>Switch transaction state machine: <code>apps/runtime/src/renderer/switch_transaction.ts</code> (WP01)</li><li>PTY stream proxy: <code>apps/runtime/src/renderer/pty_stream_proxy.ts</code> (WP01)</li><li>Capability matrix: <code>apps/runtime/src/renderer/capability_matrix.ts</code> (WP01)</li><li>Renderer adapters: specs 010, 011, 012</li></ul><p>Constraints:</p><ul><li>All-or-nothing atomicity: all terminals switch or none do.</li><li>Rollback must leave system in identical state to pre-switch.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun runtime.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP02</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t006-implement-hot-swap-execution-path" tabindex="-1">Subtask T006 - Implement hot-swap execution path <a class="header-anchor" href="#subtask-t006-implement-hot-swap-execution-path" aria-label="Permalink to &quot;Subtask T006 - Implement hot-swap execution path&quot;">​</a></h3><ul><li>Purpose: atomically transition all active terminals from source renderer to target renderer using the PTY stream proxy.</li><li>Steps: <ol><li>Implement <code>executeHotSwap(transaction, terminals, sourceAdapter, targetAdapter)</code> in <code>apps/runtime/src/renderer/hot_swap.ts</code>.</li><li>Phase 1 - Pre-validation: a. Query capability matrix to confirm both renderers support hot-swap. b. Validate all terminal PTY streams are healthy. c. If any check fails, abort before side effects and return error.</li><li>Phase 2 - Buffer activation: a. Activate PTY stream proxy buffering for all terminals simultaneously. b. Transition state machine to <code>hot-swapping</code>.</li><li>Phase 3 - Renderer swap: a. Initialize target renderer adapter for all terminals. b. If target init succeeds for all terminals, detach source renderer. c. If target init fails for any terminal, trigger rollback (T007).</li><li>Phase 4 - Replay and commit: a. Replay PTY buffers to the target renderer for each terminal. b. Verify all replays complete without errors. c. Transition state machine to <code>committing</code> then <code>committed</code>. d. Switch PTY proxies back to passthrough mode with target renderer.</li><li>Handle session context preservation: scrollback history, cursor position, env vars, cwd.</li><li>Export <code>executeHotSwap</code> for use by the switch transaction orchestrator.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/hot_swap.ts</code></li></ul></li><li>Validation: <ul><li>Integration test: hot-swap with 3 active terminals, verify all streams continuous.</li><li>Integration test: verify scrollback and cursor position match pre-swap state.</li><li>Timing test: verify completion under 3 seconds with typical terminal count.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t007-implement-rollback-logic" tabindex="-1">Subtask T007 - Implement rollback logic <a class="header-anchor" href="#subtask-t007-implement-rollback-logic" aria-label="Permalink to &quot;Subtask T007 - Implement rollback logic&quot;">​</a></h3><ul><li>Purpose: restore the previous renderer with full state recovery on any failure during the switch transaction.</li><li>Steps: <ol><li>Implement <code>executeRollback(transaction, terminals, originalAdapter)</code> in <code>apps/runtime/src/renderer/rollback.ts</code>.</li><li>Rollback sequence: a. Transition state machine to <code>rolling-back</code>. b. Teardown any partially-initialized target renderer instances. c. Re-attach the original renderer adapter to all terminals. d. Abort PTY stream proxies (discard buffer, restore original passthrough). e. Verify all terminal PTY streams are functional with original renderer. f. Transition state machine to <code>rolled-back</code>.</li><li>Emit <code>renderer.switch.rolled_back</code> event with failure reason.</li><li>Handle partial rollback: if some terminals cannot be restored, flag them as degraded and notify the user.</li><li>Preserve complete session context during rollback (scrollback, cursor, env, cwd).</li><li>Return rollback result with per-terminal status.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/rollback.ts</code></li></ul></li><li>Validation: <ul><li>Integration test: inject failure during target init, verify rollback restores original state.</li><li>Integration test: inject failure during replay, verify rollback restores original state.</li><li>Integration test: verify rollback completes under 5 seconds.</li><li>Unit test: verify rolled-back event payload includes failure reason.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t008-implement-concurrent-switch-rejection" tabindex="-1">Subtask T008 - Implement concurrent switch rejection <a class="header-anchor" href="#subtask-t008-implement-concurrent-switch-rejection" aria-label="Permalink to &quot;Subtask T008 - Implement concurrent switch rejection&quot;">​</a></h3><ul><li>Purpose: prevent multiple switch transactions from running simultaneously, which would corrupt state.</li><li>Steps: <ol><li>Add a transaction-active guard in the switch transaction module.</li><li>When a new switch is requested while a transaction is active: a. Return a structured error with <code>ConcurrentSwitchRejection</code> type. b. Include the active transaction ID, phase, and estimated completion time if available.</li><li>Wire the guard into the public <code>startSwitch()</code> entry point.</li><li>Add terminal creation queueing awareness: new terminals created during a switch are queued (implemented fully in WP03 T013, but the rejection signal is defined here).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/switch_transaction.ts</code> (guard addition)</li></ul></li><li>Validation: <ul><li>Unit test: start a transaction, attempt second start, assert rejection error with transaction details.</li><li>Unit test: after first transaction completes, second start succeeds.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t009-wire-hot-swap-and-rollback-into-switch-transaction-state-machine" tabindex="-1">Subtask T009 - Wire hot-swap and rollback into switch transaction state machine <a class="header-anchor" href="#subtask-t009-wire-hot-swap-and-rollback-into-switch-transaction-state-machine" aria-label="Permalink to &quot;Subtask T009 - Wire hot-swap and rollback into switch transaction state machine&quot;">​</a></h3><ul><li>Purpose: integrate the hot-swap and rollback execution paths as the primary switch strategy within the transaction orchestrator.</li><li>Steps: <ol><li>Implement <code>startSwitch(targetRendererId)</code> orchestrator function that: a. Checks concurrent transaction guard (T008). b. Creates a new <code>SwitchTransaction</code> in <code>pending</code> state. c. Queries capability matrix: if <code>canHotSwap</code>, call <code>executeHotSwap</code> (T006). d. On hot-swap failure, call <code>executeRollback</code> (T007). e. On hot-swap success, transition to <code>committed</code>. f. If not hot-swap capable, leave a placeholder for restart-with-restore (WP03).</li><li>Wire error propagation: all errors from hot-swap and rollback are captured in the transaction record.</li><li>Expose the orchestrator as the public API for triggering renderer switches.</li><li>Add user notification callback interface for switch progress, success, and failure.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/switch_transaction.ts</code> (orchestrator integration)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/hot_swap.ts</code> (wiring)</li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/src/renderer/rollback.ts</code> (wiring)</li></ul></li><li>Validation: <ul><li>Integration test: full happy-path hot-swap through orchestrator.</li><li>Integration test: hot-swap failure triggers rollback through orchestrator.</li><li>Integration test: non-hot-swap-capable pair returns placeholder/error until WP03.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t010-add-integration-tests-for-hot-swap-rollback-and-concurrent-rejection" tabindex="-1">Subtask T010 - Add integration tests for hot-swap, rollback, and concurrent rejection <a class="header-anchor" href="#subtask-t010-add-integration-tests-for-hot-swap-rollback-and-concurrent-rejection" aria-label="Permalink to &quot;Subtask T010 - Add integration tests for hot-swap, rollback, and concurrent rejection&quot;">​</a></h3><ul><li>Purpose: validate complete hot-swap and rollback flows under realistic conditions.</li><li>Steps: <ol><li>Create test file <code>apps/runtime/tests/integration/renderer/hot_swap.test.ts</code>: a. Test hot-swap success with 1, 3, and 5 terminals. b. Test PTY byte continuity: write known pattern before swap, verify pattern continuous after. c. Test scrollback preservation after swap. d. Test cursor position and cwd preservation.</li><li>Create test file <code>apps/runtime/tests/integration/renderer/rollback.test.ts</code>: a. Test rollback on target renderer init failure. b. Test rollback on PTY replay failure. c. Test rollback restores exact pre-swap terminal state. d. Test rollback completes under 5s SLO.</li><li>Create test file <code>apps/runtime/tests/integration/renderer/concurrent_switch.test.ts</code>: a. Test concurrent switch rejection returns correct error. b. Test sequential switches succeed.</li><li>Use mock renderer adapters that simulate real init/teardown timing.</li><li>Aim for &gt;=85% line coverage across hot-swap and rollback modules.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/renderer/hot_swap.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/renderer/rollback.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/runtime/tests/integration/renderer/concurrent_switch.test.ts</code></li></ul></li><li>Parallel: Yes (after T006/T007/T009 are integrated).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Integration tests with mock renderer adapters simulating realistic timing.</li><li>Fault injection via adapter mocks that fail at specific phases.</li><li>Byte-level verification of PTY stream continuity.</li><li>SLO timing assertions at p95 across repeated runs.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: partial renderer attachment creates split state.</li><li>Mitigation: two-phase commit with pre-validation before any detachment.</li><li>Risk: rollback fails to restore original state.</li><li>Mitigation: rollback operates on preserved original adapter references; degraded mode as last resort.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm atomicity: verify that partial hot-swap always triggers rollback.</li><li>Confirm byte-level PTY continuity in test assertions.</li><li>Confirm concurrent rejection returns actionable error details.</li><li>Confirm session context (scrollback, cursor, env, cwd) is preserved in all paths.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:31:19Z – claude-haiku – shell_pid=61191 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:33:38Z – claude-haiku – shell_pid=61191 – lane=done – Implemented: Hot-swap execution (T006), rollback logic (T007), concurrent switch rejection (T008), transaction orchestrator integration (T009), and 21 integration tests (T010). All tests passing.</li></ul>',30)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
